const css = `
@import url("https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,600;1,600&display=swap");

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: #fffdfb;
  color: #281b22;
  font-family: "DM Sans", sans-serif;
}

button,
input {
  font-family: inherit;
}

button {
  cursor: pointer;
}

a {
  text-decoration: none;
  color: inherit;
}

.app {
  min-height: 100vh;
  overflow: hidden;
}

/* TOPBAR */

.topbar {
  min-height: 35px;
  background: #281b22;
  color: white;

  display: flex;
  justify-content: center;
  align-items: center;

  gap: 12px;

  padding: 8px 20px;

  font-size: 10px;
}

.topDot {
  color: #e0bfb4;
}

/* HEADER */

.header {
  max-width: 1400px;
  height: 80px;

  margin: auto;

  padding: 0 5%;

  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
}

.logoCircle {
  width: 38px;
  height: 38px;

  border-radius: 50%;

  background: #77364c;
  color: white;

  display: grid;
  place-items: center;

  font-family: "Playfair Display", serif;
  font-size: 22px;
  font-style: italic;
}

.logo > div {
  display: flex;
  flex-direction: column;
}

.logo strong {
  font-size: 13px;
  letter-spacing: 3px;
}

.logo small {
  margin-top: 4px;
  font-size: 7px;
  letter-spacing: 1.5px;
  color: #8b7f85;
}

nav {
  display: flex;
  gap: 30px;
}

nav a {
  font-size: 11px;
  font-weight: 600;
}

.cart {
  height: 41px;

  padding: 0 17px;

  border: 0;
  border-radius: 30px;

  background: #281b22;
  color: white;

  display: flex;
  align-items: center;

  gap: 8px;

  font-size: 10px;
}

/* HERO */

.hero {
  min-height: 650px;

  padding:
    65px
    max(6%, calc((100vw - 1250px) / 2));

  background:
    radial-gradient(
      circle at 78% 30%,
      #ead0c5,
      transparent 28%
    ),
    linear-gradient(
      120deg,
      #faf5f1,
      #fffdfb,
      #f1e0da
    );

  display: grid;

  grid-template-columns:
    0.9fr 1.1fr;

  align-items: center;

  gap: 60px;
}

.subtitle {
  color: #98465f;

  font-size: 9px;
  font-weight: 700;

  letter-spacing: 2px;
}

.hero h1 {
  max-width: 620px;

  margin: 18px 0 22px;

  font-family:
    "Playfair Display",
    serif;

  font-size:
    clamp(50px, 5vw, 76px);

  line-height: 0.98;
}

.hero h1 em,
.about h2 em {
  color: #a44561;
}

.heroText > p {
  max-width: 500px;

  color: #766a70;

  font-size: 13px;

  line-height: 1.8;
}

.heroButtons {
  margin-top: 30px;

  display: flex;
  align-items: center;

  gap: 25px;
}

.discover,
.whatsapp {
  min-height: 51px;

  padding: 0 22px;

  border-radius: 30px;

  background: #77364c;
  color: white;

  display: inline-flex;
  align-items: center;

  gap: 10px;

  font-size: 10px;
  font-weight: 700;
}

.storyLink {
  padding-bottom: 4px;

  border-bottom:
    1px solid #281b22;

  font-size: 10px;
  font-weight: 700;
}

.heroAdvantages {
  margin-top: 43px;

  display: flex;

  flex-wrap: wrap;

  gap: 14px;
}

.heroAdvantages span {
  color: #786c72;

  font-size: 9px;
}

/* HERO VISUAL */

.heroVisual {
  height: 540px;

  position: relative;
}

.heroShape {
  position: absolute;

  width: 390px;
  height: 390px;

  right: 50px;
  top: 45px;

  background: #e8cfc5;

  border-radius: 50%;
}

.heroMain {
  position: absolute;

  right: 7%;
  top: 0;

  width: 56%;
  height: 90%;

  object-fit: cover;

  filter: none;

  border-radius:
    220px
    220px
    15px
    15px;

  box-shadow:
    0 30px 60px
    rgba(50,20,30,.15);
}

.heroSmall {
  position: absolute;

  left: 7%;
  bottom: 0;

  width: 31%;
  height: 43%;

  object-fit: cover;

  filter: none;

  border-radius:
    120px
    120px
    12px
    12px;

  border: 8px solid #fffdfb;
}

.heroCard {
  position: absolute;

  right: 0;
  bottom: 35px;

  width: 180px;

  padding: 17px;

  border-radius: 13px;

  background:
    rgba(255,255,255,.95);

  display: flex;
  flex-direction: column;

  box-shadow:
    0 20px 40px
    rgba(40,20,30,.12);
}

.heroCard small {
  color: #a44561;
  font-size: 7px;
  font-weight: 700;
}

.heroCard strong {
  margin: 7px 0 4px;

  font-family:
    "Playfair Display",
    serif;

  font-size: 19px;
}

.heroCard span {
  color: #776b70;
  font-size: 9px;
}

/* SERVICES */

.services {
  max-width: 1200px;

  position: relative;

  z-index: 3;

  margin: -28px auto 0;

  padding: 22px;

  border-radius: 14px;

  background: white;

  display: grid;
  grid-template-columns:
    repeat(3, 1fr);

  box-shadow:
    0 20px 50px
    rgba(40,20,30,.1);
}

.services article {
  padding: 8px 25px;

  display: flex;
  align-items: center;

  gap: 15px;

  border-right:
    1px solid #eee2dc;
}

.services article:last-child {
  border-right: 0;
}

.serviceIcon {
  font-size: 22px;
}

.services article > div {
  display: flex;
  flex-direction: column;
}

.services strong {
  font-size: 10px;
}

.services small {
  margin-top: 4px;

  color: #82767c;

  font-size: 8px;
}

/* COLLECTION */

.collection {
  max-width: 1300px;

  margin: auto;

  padding: 105px 25px;
}

.collectionTop {
  display: flex;

  align-items: end;
  justify-content: space-between;

  gap: 30px;
}

.collection h2 {
  margin: 8px 0 3px;

  font-family:
    "Playfair Display",
    serif;

  font-size: 50px;
}

.collectionTop p {
  margin: 4px 0 0;

  color: #857980;

  font-size: 9px;
}

.searchBox {
  width: 260px;
  height: 45px;

  padding: 0 15px;

  border:
    1px solid #e4dad5;

  border-radius: 30px;

  display: flex;
  align-items: center;

  gap: 9px;
}

.searchBox input {
  width: 100%;

  border: 0;

  outline: 0;

  background: transparent;

  font-size: 10px;
}

.categories {
  margin: 30px 0;

  display: flex;

  gap: 8px;

  overflow-x: auto;
}

.categories button {
  flex: 0 0 auto;

  padding: 9px 15px;

  border:
    1px solid #e5dbd6;

  border-radius: 30px;

  background: white;

  font-size: 9px;
}

.categories button.active {
  background: #281b22;
  color: white;

  border-color: #281b22;
}

/* PRODUCTS */

.products {
  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 32px 15px;
}

.productImage {
  height: 390px;

  position: relative;

  overflow: hidden;

  border-radius: 12px;

  background: #eee3de;
}

.productImage > img {
  width: 100%;
  height: 100%;

  object-fit: cover;

  transition:
    transform .4s ease,
    filter .4s ease;
}

/* PHOTO NORMALE */

.productImage > img.normal {
  filter: none;

  transform: scale(1);
}

.productImage:not(.lockedProduct):hover
img.normal {
  transform: scale(1.035);
}

/* PHOTO FLOUTÉE */

.productImage > img.blurred {
  filter: blur(17px);

  transform: scale(1.12);
}

.productImage.lockedProduct {
  cursor: pointer;
}

/* légèrement moins flou au hover */

.productImage.lockedProduct:hover
img.blurred {
  filter: blur(13px);

  transform: scale(1.14);
}

.categoryBadge {
  position: absolute;

  z-index: 5;

  top: 12px;
  left: 12px;

  padding: 7px 10px;

  border-radius: 30px;

  background: white;

  font-size: 7px;
  font-weight: 700;

  box-shadow:
    0 5px 15px
    rgba(0,0,0,.06);
}

.heart {
  position: absolute;

  z-index: 5;

  top: 12px;
  right: 12px;

  width: 36px;
  height: 36px;

  border: 0;

  border-radius: 50%;

  background: white;

  font-size: 18px;
}

.addCart {
  position: absolute;

  z-index: 5;

  left: 10px;
  right: 10px;
  bottom: 10px;

  height: 39px;

  border: 0;

  border-radius: 30px;

  background:
    rgba(40,27,34,.93);

  color: white;

  font-size: 8px;
  font-weight: 700;

  opacity: 0;

  transform:
    translateY(7px);

  transition: .25s;
}

