  to {
    opacity: 1;

    transform: none;
  }
}

.close {
  position: absolute;

  right: 13px;
  top: 13px;

  width: 35px;
  height: 35px;

  border: 0;

  border-radius: 50%;

  background: #f5eeee;

  font-size: 20px;
}

.modalLogo {
  width: 55px;
  height: 55px;

  margin: auto;

  border-radius: 50%;

  background: #77364c;

  color: white;

  display: grid;
