.selectedProduct strong {
  margin-top: 3px;

  font-family:
    "Playfair Display",
    serif;
}

.loginModal h2 {
  margin: 20px 0 10px;

  font-family:
    "Playfair Display",
    serif;

  font-size: 27px;
}

